$(function(){$("footer").text(new Date().getFullYear());var t=$(".about, .portfolio, .findme");$(document).on("click",".h-icon",function(){var a=$(this);$(".active").removeClass("active"),a.addClass("active");var i=a.attr("class").split(/\s+/),o=($("."+(i[1]?i[1].split("-")[2]:"")).attr("class")||"").match(/position(\d+)/),s=(o?parseInt(o[1],10):0)-3,n=t.map(function(){var t=($(this).attr("class")||"").match(/position(\d+)/);return(t?parseInt(t[1],10):0)-s}).get();t.removeClass(function(t,a){return(a.match(/\bposition\d+\b/g)||[]).join(" ")}).each(function(t){$(this).addClass("position"+n[t])})})});